<template>
  <h2>我是About的内容</h2>
</template>

<script>
export default {
  name: "About",

  // 通过路由规则 进入该组件时调用
  beforeRouteEnter(to, from, next) {
    console.log("beforeRouteEnter");

    console.log("新闻的独享路由");

    if (to.meta.isAuth) {
      //判断是否需要鉴权
      if (localStorage.getItem("school") == "at") {
        next();
      } else {
        alert("学校名不对，无权访问");
      }
    } else {
      next();
    }
  },

  // 通过路由规则 离开该组件时调用
  beforeRouteLeave(to, from, next) {
    console.log("beforeRouteLeave");
    next();
  },
};
</script>

